result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/board.py", "content": """"Chess board representation: 10x12 mailbox, FEN parsing, make/unmake move.

Squares are indices 0..119; valid squares are 21..98.
A1 = 21, H1 = 28, A8 = 91, H8 = 98.  sq(file, rank) = 21 + file + 10*rank.
White pieces are positive ints, black negative, off-board squares are OFF.
"""
from __future__ import annotations

# --- Piece codes -----------------------------------------------------------
EMPTY = 0
PAWN, KNIGHT, BISHOP, ROOK, QUEEN, KING = 1, 2, 3, 4, 5, 6
OFF = 7  # off-board sentinel

WHITE, BLACK = 1, -1

PIECE_FROM_CHAR = {"P": PAWN, "N": KNIGHT, "B": BISHOP,
                   "R": ROOK, "Q": QUEEN, "K": KING}
CHAR_FROM_PIECE = {v: k for k, v in PIECE_FROM_CHAR.items()}

# --- Directions / offsets --------------------------------------------------
N, S, E, W = 10, -10, 1, -1
KNIGHT_OFFS = (-21, -19, -12, -8, 8, 12, 19, 21)
KING_OFFS = (-11, -10, -9, -1, 1, 9, 10, 11)
BISHOP_DIRS = (-11, -9, 9, 11)
ROOK_DIRS = (-10, -1, 1, 10)
QUEEN_DIRS = BISHOP_DIRS + ROOK_DIRS

# --- Castling rights bits ---------------------------------------------------
WK, WQ, BK, BQ = 1, 2, 4, 8

# --- Move flags -------------------------------------------------------------
FLAG_NORMAL, FLAG_DOUBLE, FLAG_EP, FLAG_CASTLE = 0, 1, 2, 3

# A move is a tuple: (frm, to, promo_piece_type_or_0, flag)


def sq_index(file: int, rank: int) -> int:
    """file, rank in 0..7 -> mailbox index."""
    return 21 + file + 10 * rank


def sq_name(i: int) -> str:
    return "abcdefgh"[i % 10 - 1] + str(i // 10 - 1)


def name_to_sq(s: str) -> int:
    return sq_index("abcdefgh".index(s[0]), int(s[1]) - 1)


SQUARES = [sq_index(f, r) for r in range(8) for f in range(8)]

# Squares whose involvement in a move strips castling rights.
CASTLE_MASK = [WK | WQ | BK | BQ] * 120
CASTLE_MASK[name_to_sq("e1")] &= ~(WK | WQ)
CASTLE_MASK[name_to_sq("h1")] &= ~WK
CASTLE_MASK[name_to_sq("a1")] &= ~WQ
CASTLE_MASK[name_to_sq("e8")] &= ~(BK | BQ)
CASTLE_MASK[name_to_sq("h8")] &= ~BK
CASTLE_MASK[name_to_sq("a8")] &= ~BQ

START_FEN = "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1"


class Board:
    __slots__ = ("board", "side", "castling", "ep", "kings", "history")

    def __init__(self, fen: str = START_FEN):
        self.set_fen(fen)

    # -- setup ---------------------------------------------------------------
    def set_fen(self, fen: str) -> None:
        parts = fen.split()
        self.board = [OFF] * 120
        for i in SQUARES:
            self.board[i] = EMPTY
        rows = parts[0].split("/")
        if len(rows) != 8:
            raise ValueError(f"bad FEN board: {parts[0]}")
        for r, row in enumerate(rows):          # rows[0] is rank 8
            f = 0
            for ch in row:
                if ch.isdigit():
                    f += int(ch)
                else:
                    pt = PIECE_FROM_CHAR[ch.upper()]
                    self.board[sq_index(f, 7 - r)] = pt if ch.isupper() else -pt
                    f += 1
            if f != 8:
                raise ValueError(f"bad FEN rank: {row}")
        self.side = WHITE if parts[1] == "w" else BLACK
        self.castling = 0
        if len(parts) > 2 and parts[2] != "-":
            for ch in parts[2]:
                self.castling |= {"K": WK, "Q": WQ, "k": BK, "q": BQ}[ch]
        self.ep = name_to_sq(parts[3]) if len(parts) > 3 and parts[3] != "-" else 0
        self.kings = {WHITE: 0, BLACK: 0}
        for i in SQUARES:
            if self.board[i] == KING:
                self.kings[WHITE] = i
            elif self.board[i] == -KING:
                self.kings[BLACK] = i
        self.history = []

    # -- attacks --------------------------------------------------------------
    def attacked(self, sq: int, by: int) -> bool:
        """Is `sq` attacked by any piece of color `by`?"""
        b = self.board
        if by == WHITE:
            if b[sq - 9] == PAWN or b[sq - 11] == PAWN:
                return True
        else:
            if b[sq + 9] == -PAWN or b[sq + 11] == -PAWN:
                return True
        kn, kg, qn = KNIGHT * by, KING * by, QUEEN * by
        for o in KNIGHT_OFFS:
            if b[sq + o] == kn:
                return True
        for o in KING_OFFS:
            if b[sq + o] == kg:
                return True
        bn = BISHOP * by
        for d in BISHOP_DIRS:
            t = sq + d
            while b[t] == EMPTY:
                t += d
            p = b[t]
            if p == bn or p == qn:
                return True
        rn = ROOK * by
        for d in ROOK_DIRS:
            t = sq + d
            while b[t] == EMPTY:
                t += d
            p = b[t]
            if p == rn or p == qn:
                return True
        return False

    def in_check(self, side: int | None = None) -> bool:
        s = self.side if side is None else side
        return self.attacked(self.kings[s], -s)

    # -- make / unmake ---------------------------------------------------------
    def make(self, move: tuple) -> None:
        frm, to, promo, flag = move
        b = self.board
        piece = b[frm]
        captured = b[to]
        self.history.append((move, captured, self.castling, self.ep))
        b[to] = (promo * piece if False else promo) if promo else piece
        # note: `promo` stores a signed piece code already
        b[frm] = EMPTY
        self.ep = 0
        if flag == FLAG_DOUBLE:
            self.ep = (frm + to) >> 1
        elif flag == FLAG_EP:
            b[to - 10 * self.side] = EMPTY       # remove the captured pawn
        elif flag == FLAG_CASTLE:
            if to > frm:                          # king side
                b[frm + 1] = b[frm + 3]; b[frm + 3] = EMPTY
            else:                                 # queen side
                b[frm - 1] = b[frm - 4]; b[frm - 4] = EMPTY
        if piece == KING or piece == -KING:
            self.kings[self.side] = to
        self.castling &= CASTLE_MASK[frm] & CASTLE_MASK[to]
        self.side = -self.side

    def unmake(self) -> None:
        move, captured, castling, ep = self.history.pop()
        frm, to, promo, flag = move
        self.side = -self.side
        b = self.board
        piece = b[to]
        if promo:
            piece = PAWN * self.side
        b[frm] = piece
        b[to] = captured
        if flag == FLAG_EP:
            b[to - 10 * self.side] = -PAWN * self.side
        elif flag == FLAG_CASTLE:
            if to > frm:
                b[frm + 3] = b[frm + 1]; b[frm + 1] = EMPTY
            else:
                b[frm - 4] = b[frm - 1]; b[frm - 1] = EMPTY
        if piece == KING or piece == -KING:
            self.kings[self.side] = frm
        self.castling = castling
        self.ep = ep

    def legal_moves(self):
        from movegen import gen_legal
        return gen_legal(self)

    def __str__(self) -> str:
        out = []
        for r in range(7, -1, -1):
            row = [".ABCDEFGH"[0] if False else "."]  # placeholder replaced below
            cells = []
            for f in range(8):
                p = self.board[sq_index(f, r)]
                if p == EMPTY:
                    cells.append(".")
                else:
                    c = CHAR_FROM_PIECE[abs(p)]
                    cells.append(c if p > 0 else c.lower())
            out.append(f"{r+1} " + " ".join(cells))
        out.append("  a b c d e f g h")
        return "\n".join(out)
"})
